(function(root){
  'use strict';
  const D=root.InstagramArchiveData;
  let profile='seulgi',view='profile',postId='',slide=0,returnView='profile';
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date=p=>p.date.replaceAll('-','.');
  const find=id=>D.posts.find(p=>p.id===id);
  const own=()=>D.posts.filter(p=>p.owner===profile).sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
  const feed=()=>D.posts.slice().sort((a,b)=>(b.date+(b.time||'')).localeCompare(a.date+(a.time||'')));
  const photo=img=>img?.source?.startsWith('https://img-cdn.theqoo.net/')?'instagram/'+img.source.split('/').pop().split('?')[0]:'';
  const images=p=>p.images.filter(img=>photo(img));
  const avatar=p=>`<span class="ig2-avatar" style="--ig-color:${p.color}">${p.initial||esc(p.name[0])}</span>`;
  const label=p=>esc(p.handle);
  function header(title,back=false){return `<header class="ig2-header"><button ${back?'data-ig-back':'data-nav="phonehome"'} aria-label="返回">‹</button><strong>${esc(title)}</strong><button data-nav="phonehome" aria-label="返回桌面">⌂</button></header>`}
  function bottom(){return `<nav class="ig2-bottom"><button data-ig-view="feed" class="${view==='feed'?'selected':''}" aria-label="动态首页"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/></svg></button><button data-ig-view="profile" class="${view==='profile'?'selected':''}" aria-label="个人主页">${avatar(D.profiles[profile])}</button><button data-nav="notebook" aria-label="已保存的记录"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 3h14v18l-7-4-7 4z"/></svg></button></nav>`}
  function tile(p){const pics=images(p),img=pics[0];return `<button class="ig2-tile ${img?'':'ig2-text-tile'}" data-ig-post="${esc(p.id)}" aria-label="打开 ${date(p)} ${esc(p.title)}">${img?`<img src="${esc(photo(img))}" alt="${esc(img.alt)}" loading="lazy">`:`<span>${esc(p.title)}</span>`}${pics.length>1?'<b aria-hidden="true">▣</b>':''}</button>`}
  function profilePage(){const p=D.profiles[profile],posts=own();return `${header(p.handle)}<div class="nf-scroll ig2-scroll"><section class="ig2-profile"><div class="ig2-profile-top">${avatar(p)}<div class="ig2-stat"><strong>${posts.length}</strong><span>게시물</span></div><div class="ig2-stat"><strong>♡</strong><span>기록</span></div></div><strong class="ig2-name">${esc(p.name)}</strong><p>${profile==='seulgi'?'SEULGI':'IRENE'}</p><div class="ig2-profile-actions"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Instagram ↗</a><button data-ig-view="feed">게시물 보기</button></div></section><div class="ig2-account-bar">${Object.entries(D.profiles).map(([key,item])=>`<button data-ig-profile="${key}" class="${key===profile?'active':''}">${avatar(item)}<span>${label(item)}</span></button>`).join('')}</div><div class="ig2-grid-head"><span>▦</span><small>게시물</small></div><div class="ig2-grid">${posts.map(tile).join('')}</div></div>${bottom()}`}
  function feedCard(p,state){const a=D.profiles[p.owner],pics=images(p),img=pics[0],saved=state.igSaved.includes(p.id);return `<article class="ig2-feed-card"><header><button data-ig-profile="${p.owner}" aria-label="${label(a)} 主页">${avatar(a)}</button><button data-ig-profile="${p.owner}"><strong>${label(a)}</strong><small>${date(p)}</small></button><span>•••</span></header><button class="ig2-feed-media ${img?'':'text'}" data-ig-post="${esc(p.id)}" aria-label="查看帖子">${img?`<img src="${esc(photo(img))}" alt="${esc(img.alt)}" loading="lazy">`:`<span>${esc(p.title)}</span>`}${pics.length>1?`<i>1/${pics.length}</i>`:''}</button><div class="ig2-feed-actions"><button data-ig-post="${esc(p.id)}" aria-label="查看帖子">♡</button><button data-ig-post="${esc(p.id)}" aria-label="查看内容">▢</button><button data-ig-save="${esc(p.id)}" aria-label="${saved?'取消收藏':'收藏'}" class="bookmark">${saved?'◆':'♧'}</button></div><div class="ig2-feed-copy"><strong>${label(a)}</strong> ${esc(p.caption||p.title)}${p.translation?`<small>${esc(p.translation)}</small>`:''}</div><button class="ig2-open-post" data-ig-post="${esc(p.id)}">查看图片与来源</button></article>`}
  function feedPage(state){return `${header('Instagram')}<div class="nf-scroll ig2-scroll">${feed().map(p=>feedCard(p,state)).join('')}</div>${bottom()}`}
  function postPage(state){const p=find(postId)||D.posts[0],a=D.profiles[p.owner],pics=images(p),img=pics[slide],saved=state.igSaved.includes(p.id);return `${header('게시물',true)}<div class="nf-scroll ig2-scroll ig2-post"><header class="ig2-post-author"><button data-ig-profile="${p.owner}">${avatar(a)}</button><button data-ig-profile="${p.owner}"><strong>${label(a)}</strong><small>${date(p)}${p.time?' · '+esc(p.time):''}</small></button></header>${img?`<div class="ig2-stage" tabindex="0" aria-label="图片 ${slide+1}，共 ${pics.length} 张"><img src="${esc(photo(img))}" alt="${esc(img.alt)}">${pics.length>1?`<span>${slide+1}/${pics.length}</span>`:''}</div>${pics.length>1?`<div class="ig2-pager"><button data-ig-step="-1" ${slide===0?'disabled':''} aria-label="上一张">‹</button><div>${pics.map((_,i)=>`<i class="${i===slide?'active':''}"></i>`).join('')}</div><button data-ig-step="1" ${slide===pics.length-1?'disabled':''} aria-label="下一张">›</button></div>`:''}`:`<div class="ig2-stage ig2-no-photo"><span>${esc(p.title)}</span></div>`}<div class="ig2-post-body"><div class="ig2-post-actions"><button data-ig-save="${esc(p.id)}" aria-label="${saved?'取消收藏':'收藏'}" class="${saved?'saved':''}">${saved?'♥':'♡'}</button><button data-ig-save="${esc(p.id)}" aria-label="${saved?'取消保存':'保存到备忘录'}">${saved?'◆':'♧'}</button></div><p><strong>${label(a)}</strong> ${esc(p.caption||p.title)}</p>${p.translation?`<p class="ig2-translation">${esc(p.translation)}</p>`:''}${p.comment?`<div class="ig2-comment"><strong>${esc(p.comment.account)}</strong> ${esc(p.comment.text)}<small>${esc(p.comment.translation)}</small></div>`:''}<time>${date(p)}</time><details class="ig2-source"><summary>来源</summary>${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">原帖 ↗</a>`:''}${p.archive?`<a href="${esc(p.archive)}" target="_blank" rel="noopener noreferrer">存档 ↗</a>`:''}</details></div></div>`}
  function html(state){return `<section class="nf-app ia-app ig2-app">${postId?postPage(state):view==='feed'?feedPage(state):profilePage()}</section>`}
  function selectPost(id){const p=find(id);if(!p)return false;postId=id;profile=p.owner;slide=0;return true}
  function savedCards(state){const records=state.igSaved.map(find).filter(Boolean);return records.length?`<section class="ia-notebook"><small>Instagram</small>${records.map(p=>`<button class="nf-note-record" data-ig-open="${esc(p.id)}"><span>@${esc(p.account)} · ${date(p)}</span><strong>${esc(p.title)}</strong><p>${esc(p.summary)}</p></button>`).join('')}</section>`:''}
  function bind(ctx){const s=ctx.screen,redraw=ctx.render;
    s.querySelectorAll('[data-ig-profile]').forEach(b=>b.onclick=()=>{profile=b.dataset.igProfile;postId='';view='profile';slide=0;redraw()});
    s.querySelectorAll('[data-ig-view]').forEach(b=>b.onclick=()=>{view=b.dataset.igView;postId='';redraw()});
    s.querySelectorAll('[data-ig-post]').forEach(b=>b.onclick=()=>{returnView=view;selectPost(b.dataset.igPost);redraw()});
    s.querySelectorAll('[data-ig-back]').forEach(b=>b.onclick=()=>{postId='';slide=0;view=returnView;redraw()});
    s.querySelectorAll('[data-ig-save]').forEach(b=>b.onclick=()=>ctx.onSave(b.dataset.igSave));
    function step(n){const p=find(postId);if(!p)return;const next=Math.max(0,Math.min(images(p).length-1,slide+n));if(next===slide)return;const y=s.querySelector('.nf-scroll')?.scrollTop||0;slide=next;redraw();const sc=s.querySelector('.nf-scroll');if(sc)sc.scrollTop=y}
    s.querySelectorAll('[data-ig-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.igStep)));
    const stage=s.querySelector('.ig2-stage');if(stage){let x=0;stage.addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX},{passive:true});stage.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>45)step(dx<0?1:-1)},{passive:true});stage.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();step(e.key==='ArrowRight'?1:-1)}}}
  }
  root.InstagramArchive={html,bind,selectPost,savedCards,posts:()=>D.posts};
})(window);
